<script setup>
import { splitDecisionHistory } from './utils/decision-history.js';
const state = ref(null);
const email = ref(''); const password = ref(''); const message = ref('');
const editingBrief = ref(false); const contextPreview = ref(null); const codingReview = ref(null);
const brief = reactive({ id: '', name: '', objective: '', text: '' });
const observation = reactive({ requestId: '', sessionId: '', sessionUrl: '', execution: 'exited', observedAt: '', markerVerified: false });
const busy = ref(false); const error = ref(''); const checking = ref(true);
const dollars = value => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 3 }).format(value / 1e6);
const labels = { thinking: 'Waiting for Eve', held: 'Needs operator review', awaiting_approval: 'Your decision', approved: 'Committed', needs_context: 'Needs your context', coding_dispatched: 'Coding handoff recorded' };
const errors = { UNRESOLVED_MODEL_ATTEMPT: 'A prior request needs review before another can run.', CONTEXT_EXPIRED: 'The project brief has expired. Refresh it with the operator before asking Eve.', ADMISSION_PAUSED: 'New requests are paused.', APPROVAL_MISMATCH: 'This proposal no longer matches the current brief. Refresh to review the latest state.', CODING_NOT_ENABLED: 'Coding dispatch is not connected or its verification has expired.', CONTEXT_PREVIEW_STALE: 'This preview expired or the brief changed. Preview again.', CONTEXT_WORK_UNRESOLVED: 'Resolve the active or uncertain work before changing the project brief.', CODING_PREFLIGHT_FAILED: 'Repository verification failed. No coding dispatch was sent.', CODING_ADMISSION_PAUSED: 'Coding admission is paused or another job occupies the slot.', CODING_RELEASE_UNVERIFIED: 'Record the provider session ending, then refresh its evidence before releasing the slot.' };
async function api(path, body) {
  const response = await fetch(`/api/${path}`, { method: body === undefined ? 'GET' : 'POST', credentials: 'same-origin', headers: body === undefined ? {} : { 'content-type': 'application/json' }, body: body === undefined ? undefined : JSON.stringify(body) });
  const data = await response.json();
  if (!response.ok) { if (response.status === 401) state.value = null; throw new Error(errors[data.error] || (response.status === 401 ? 'Sign in to continue.' : 'This action could not be completed. Refresh to check its status.')); }
  return data;
}
async function refresh() { state.value = await api('steward/state'); }
async function action(fn) { busy.value = true; error.value = ''; try { await fn(); } catch (e) { error.value = e.message; } finally { busy.value = false; } }
async function login() { await action(async () => { try { await api('auth/sign-in/email', { email: email.value, password: password.value }); await refresh(); } finally { password.value = ''; } }); }
async function propose() { await action(async () => { await api('steward/propose', { requestId: crypto.randomUUID(), projectId: state.value.project.id, message: message.value }); message.value = ''; await refresh(); }); }
async function approve(record) { await action(async () => { await api('steward/approve', { requestId: record.id, proposalHash: record.proposalHash }); await refresh(); }); }
function editBrief() { editingBrief.value = true; contextPreview.value = null; Object.assign(brief, { id: state.value.project.id, name: state.value.project.name, objective: state.value.project.objective, text: state.value.project.sources.map(s => s.content).join('\n\n') }); }
async function loadBrief(event) { const file = event.target.files?.[0]; if (!file) return; if (file.size > 16000 || !/\.(md|txt)$/i.test(file.name)) { error.value = 'Choose a Markdown or text file up to 16 KB.'; return; } const text = await file.text(); if (text.length > 4000) { error.value = 'Keep the brief under 4,000 characters.'; return; } brief.text = text; contextPreview.value = null; }
async function previewBrief() { await action(async () => { const at = new Date(); contextPreview.value = await api('steward/context/preview', { project: { id: brief.id, name: brief.name, objective: brief.objective, sources: [{ id: 'brief', title: 'Owner-approved project brief', revision: at.toISOString(), observedAt: at.toISOString(), expiresAt: new Date(at.getTime() + 7 * 86400000).toISOString(), content: brief.text, exposure: 'model_allowed' }], codingCandidates: [] } }); }); }
async function applyBrief() { await action(async () => { await api('steward/context/apply', { previewId: contextPreview.value.id, expectedRevision: contextPreview.value.expectedRevision }); contextPreview.value = null; editingBrief.value = false; codingReview.value = null; await refresh(); }); }
async function reviewCoding(record) { await action(async () => { codingReview.value = await api('steward/coding/review', { requestId: record.id, proposalHash: record.proposalHash }); }); }
async function dispatchCoding() { await action(async () => { const r = codingReview.value; await api('steward/coding/approve', { requestId: r.requestId, proposalHash: r.proposalHash, reviewHash: r.reviewHash }); codingReview.value = null; await refresh(); }); }
function observeJob(job) { Object.assign(observation, { requestId: job.id, sessionId: job.session?.id || '', sessionUrl: job.session?.url || '', execution: 'exited', observedAt: new Date().toISOString(), markerVerified: false }); }
async function saveObservation() { await action(async () => { await api('steward/coding/observe', observation); observation.requestId = ''; await refresh(); }); }
async function signOut() { await action(async () => { await api('auth/sign-out', {}); state.value = null; message.value = ''; contextPreview.value = null; codingReview.value = null; editingBrief.value = false; brief.text = ''; }); }
onMounted(async () => { try { await refresh(); } catch { /* Show the owner login without leaking setup details. */ } finally { checking.value = false; } });
const decisionGroups = computed(() => {
  const { current, historical } = splitDecisionHistory(state.value?.requests, state.value?.project?.revision);
  return [
    { key: 'current', heading: 'Current project', note: 'Decisions made under the approved brief you are working from now.', empty: 'No decisions yet for the current brief. Your next question starts its loop; earlier decisions stay below for reference.', records: current },
    { key: 'historical', heading: 'Earlier projects', note: 'Recorded under a previous brief. These stay inspectable but cannot be approved for the current brief.', empty: '', records: historical },
  ].filter(group => group.records.length || group.key === 'current');
});
const blocked = computed(() => state.value?.paused || state.value?.providerAttempts >= state.value?.maxProviderAttempts || !state.value?.contextFresh || state.value?.requests.some(r => ['thinking', 'held'].includes(r.status)));
</script>
<template>
  <main>
    <header><a class="brand" href="/">S<span>Project Steward</span></a><button v-if="state" class="quiet" :disabled="busy" @click="signOut">Sign out</button><span v-else class="tag">PRIVATE ALPHA</span></header>
    <div v-if="checking" class="loading" role="status">Opening your workspace…</div>
    <section v-else-if="!state" class="login">
      <p class="eyebrow">ONE PROJECT. THE NEXT USEFUL STEP.</p>
      <h1>Keep the work<br>moving.</h1>
      <p class="intro">Your project’s current context, considered decisions, and commitments in one place.</p>
      <form @submit.prevent="login"><label>Email<input v-model="email" type="email" autocomplete="username" required></label><label>Password<input v-model="password" type="password" autocomplete="current-password" required></label><button :disabled="busy">{{ busy ? 'Signing in…' : 'Open my workspace' }}</button></form>
      <p class="muted">Owner access only. Account creation is managed separately.</p>
    </section>
    <template v-else>
      <section class="heading"><p class="eyebrow">YOUR WORKSPACE</p><h1>{{ state.project.name }}</h1><p class="intro">{{ state.project.objective }}</p><div class="meta"><span class="tag" :class="{ warning: !state.contextFresh }">{{ state.contextFresh ? 'Context current' : 'Context expired' }}</span><span>Eve · {{ state.judge }}</span></div></section>
      <section v-if="editingBrief" class="card">
        <h2>Update project brief</h2><p>Paste text or load a Markdown/text file. Chat messages do not replace this brief. The new brief is valid for seven days; old decisions remain in history. Coding candidates are cleared and must be configured separately.</p>
        <form @submit.prevent="previewBrief"><label>Project ID<input v-model="brief.id" pattern="[a-z0-9][a-z0-9-]{0,63}" required></label><label>Project name<input v-model="brief.name" maxlength="120" required></label><label>Objective<textarea v-model="brief.objective" maxlength="4000" required></textarea></label><label>Load a file<input type="file" accept=".md,.txt,text/plain,text/markdown" @change="loadBrief"></label><label>Project brief<textarea v-model="brief.text" rows="10" maxlength="4000" required></textarea></label><p class="muted">Preview saves a draft to your hosted workspace without calling a model. Approval allows the exact previewed brief to be sent to Eve and the configured model with future questions.</p><button :disabled="busy">Preview change</button> <button type="button" class="quiet" @click="editingBrief = false; contextPreview = null">Cancel</button></form>
        <div v-if="contextPreview" class="notice"><h3>Review the exact new context</h3><p>{{ contextPreview.previousProject.name }} ({{ contextPreview.previousProject.id }}) → {{ contextPreview.project.name }} ({{ contextPreview.project.id }})</p><p>{{ contextPreview.project.objective }}</p><pre>{{ contextPreview.project.sources[0].content }}</pre><p>Valid through {{ new Date(contextPreview.project.sources[0].expiresAt).toLocaleString() }}. {{ contextPreview.historicalCommitments }} commitments stay in history. Prior proposals cannot be approved against the new brief. {{ contextPreview.providerAttempts }} model attempts and {{ dollars(contextPreview.reservedMicros) }} reserved allowance are retained.</p><button :disabled="busy" @click="applyBrief">Approve this preview and use brief</button></div>
      </section>
      <section v-if="codingReview" class="card"><h2>Approve one coding assignment</h2><p>{{ codingReview.spec.objective }}</p><p>{{ codingReview.spec.acceptance }}</p><p>Repository: {{ codingReview.spec.repository }} ({{ codingReview.spec.visibility }}). Base: {{ codingReview.spec.baseBranch }} at {{ codingReview.spec.baseSha }}.</p><p>Allowed files: {{ codingReview.spec.allowedPaths.join(', ') }}</p><p>Required checks: {{ codingReview.spec.requiredChecks.map(c => c.name).join(', ') }}. Task branch: {{ codingReview.branch }}.</p><p>One Claude routine session may write that branch and open a draft PR. No merge, deployment or paid overage. Approval expires {{ new Date(codingReview.expiresAt).toLocaleString() }}.</p><button :disabled="busy" @click="dispatchCoding">Approve and start Claude</button> <button class="quiet" @click="codingReview = null">Cancel</button></section>
      <section v-if="state.codingJobs?.length" class="card"><h2>Coding work</h2><article v-for="job in state.codingJobs" :key="job.id"><h3>{{ job.spec.objective }}</h3><p>Dispatch: {{ job.dispatch }}. Execution: {{ job.execution }} (provider observation).</p><p v-if="job.stopRequested" class="notice">New work is paused. Stopping the remote session is not confirmed.</p><a v-if="job.session" :href="job.session.url" target="_blank" rel="noopener noreferrer">Open Claude session</a><p v-if="job.result">GitHub evidence: {{ job.result.result }} <a v-if="job.result.prUrl" :href="job.result.prUrl" target="_blank" rel="noopener noreferrer">Review PR</a></p><button class="quiet" :disabled="busy" @click="action(async () => { await api('steward/coding/reconcile', { requestId: job.id }); await refresh(); })">Refresh GitHub evidence</button> <button class="quiet" :disabled="busy" @click="observeJob(job)">Record provider observation</button> <button class="quiet" :disabled="busy" @click="action(async () => { await api('steward/coding/release', { requestId: job.id }); await refresh(); })">Release verified finished slot</button></article>
        <form v-if="observation.requestId" @submit.prevent="saveObservation"><p>Record what you observed in Claude's session UI. A PR alone does not prove the session ended.</p><label>Session ID<input v-model="observation.sessionId" required></label><label>Session URL<input v-model="observation.sessionUrl" type="url" required></label><label>Observed state<select v-model="observation.execution"><option>running</option><option>exited</option><option>stopped</option></select></label><label>Observed at (ISO timestamp)<input v-model="observation.observedAt" required></label><label><input v-model="observation.markerVerified" type="checkbox" required>I verified the task marker in this session.</label><button :disabled="busy">Save observation</button></form>
      </section>
      <div class="columns">
        <div>
          <section class="card ask"><h2>What needs attention?</h2><p>Ask for a next step, surface a blocker, or propose a commitment.</p><form @submit.prevent="propose"><label class="sr-only" for="request">Request to Eve</label><textarea id="request" v-model="message" maxlength="2000" rows="4" :disabled="busy || blocked" placeholder="What should I focus on next?" required></textarea><button :disabled="busy || blocked || !message.trim()">{{ busy ? 'Working…' : 'Ask Eve' }}</button></form><p v-if="blocked" class="notice">{{ state.paused ? 'New model requests are paused.' : state.providerAttempts >= state.maxProviderAttempts ? 'The pilot model-attempt limit has been reached.' : !state.contextFresh ? 'The brief needs a fresh owner-approved update.' : 'A prior model attempt needs review. Refresh its status; another attempt will not start automatically.' }}</p></section>
          <div class="section-title"><h2>Decisions</h2><button class="quiet" :disabled="busy" @click="action(refresh)">Refresh status</button></div>
          <p v-if="!state.requests.length" class="empty">Your first question starts the loop.</p>
          <template v-else><template v-for="group in decisionGroups" :key="group.key">
          <h3 class="group-heading">{{ group.heading }}</h3><p class="muted">{{ group.note }}</p>
          <p v-if="!group.records.length" class="empty">{{ group.empty }}</p>
          <article v-for="record in group.records" :key="record.id" class="card decision"><div class="meta"><span class="tag">{{ labels[record.status] || record.status }}</span><time>{{ new Date(record.createdAt).toLocaleString() }}</time></div><p class="request">{{ record.message }}</p><template v-if="record.proposal"><h3>{{ record.proposal.title }}</h3><p>{{ record.proposal.rationale }}</p><p v-if="record.proposal.question" class="notice">{{ record.proposal.question }}</p><p class="muted">Based on: {{ record.proposal.citations.join(', ') }}</p><details v-if="record.proposal.kind === 'coding'"><summary>Proposed coding scope</summary><pre>{{ record.contextSnapshot.codingCandidates.find(c => c.id === record.proposal.candidateId)?.spec }}</pre></details><p v-if="record.contextRevision !== state.project.revision" class="notice">Historical context. This proposal cannot be approved for the current brief.</p><p v-if="record.proposal.kind === 'coding' && !state.codingEnabled" class="notice">Coding dispatch is not configured or its verification has expired.</p><button v-if="record.status === 'awaiting_approval' && record.proposal.kind === 'coding' && state.codingEnabled && record.contextRevision === state.project.revision" :disabled="busy || !state.contextFresh" @click="reviewCoding(record)">Review coding assignment</button><button v-if="record.status === 'awaiting_approval' && record.proposal.kind === 'commitment' && record.contextRevision === state.project.revision" :disabled="busy || !state.contextFresh" @click="approve(record)">Approve commitment</button></template><p v-else class="muted">{{ record.status === 'held' ? 'Eve did not return a verified proposal. The attempt is held for operator review.' : 'The request was saved before contacting Eve. Refresh to check for a result.' }}</p><p v-if="record.provider?.httpStatus === 429" class="notice">The model gateway returned 429 (rate limited). No automatic retry was sent.</p></article>
          </template></template>
        </div>
        <aside>
          <section class="card"><p class="eyebrow">FOLLOW THROUGH</p><h2>Commitments</h2><p v-if="!state.commitments.length" class="muted">Approved commitments will appear here.</p><div v-for="item in state.commitments" :key="item.id" class="commitment"><h3>{{ item.title }}</h3><p>{{ item.rationale }}</p></div></section>
          <section class="card"><h2>Project brief</h2><button class="quiet" :disabled="busy" @click="editBrief">Update project brief</button><details v-for="source in state.project.sources" :key="source.id"><summary>{{ source.title }}</summary><p class="source">{{ source.content }}</p><p class="muted">Expires {{ new Date(source.expiresAt).toLocaleString() }}</p></details><p class="muted">Only this approved brief, current commitments, and your request are sent to Eve and the configured model.</p></section>
          <section class="card"><h2>Model allowance</h2><p class="allowance">{{ dollars(state.reservedMicros) }} <span>/ {{ dollars(state.budgetMicros) }}</span></p><p class="muted">{{ state.providerAttempts }} / {{ state.maxProviderAttempts }} pilot model attempts. Reserved allowance, not a bill. Uncertain attempts keep their reservation until reviewed.</p><button class="quiet" :disabled="busy || state.paused" @click="action(async () => { await api('steward/pause', {}); await refresh(); })">{{ state.paused ? 'Requests paused' : 'Pause new requests' }}</button></section>
        </aside>
      </div>
    </template>
    <p v-if="error" class="error" role="alert">{{ error }}</p>
    <footer>Small steps. Clear decisions. Your approval.</footer>
  </main>
</template>
<style>
:root{font-family:ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#263b36;background:#f4f5ef;font-synthesis:none}*{box-sizing:border-box}body{margin:0}main{max-width:1120px;margin:auto;padding:24px 32px}header{display:flex;justify-content:space-between;align-items:center;padding-bottom:24px;border-bottom:1px solid #d7ddd2}.brand{display:flex;align-items:center;gap:12px;text-decoration:none;color:inherit;font-size:30px;font-family:Georgia,serif}.brand span{font:600 15px ui-sans-serif,system-ui;letter-spacing:.02em}button,input,textarea{font:inherit}button{cursor:pointer;background:#284d42;color:white;border:1px solid #284d42;border-radius:8px;padding:12px 18px;font-weight:600}button:disabled{opacity:.5;cursor:default}.quiet{background:transparent;color:#284d42;border-color:#c3cfc4;padding:8px 12px}.tag{font-size:11px;letter-spacing:.06em;text-transform:uppercase;border-radius:5px;background:#e1e9dd;padding:6px 9px;white-space:nowrap}.warning{background:#f3dfba}.login{max-width:460px;margin:70px auto 90px}.eyebrow{font-size:11px;letter-spacing:.14em;font-weight:700;color:#64796b}h1{font:normal clamp(36px,5vw,60px)/1.1 Georgia,serif;margin:16px 0 22px;letter-spacing:-.035em}h2{font-size:18px;margin:0 0 14px}h3{font-size:17px;line-height:1.4;margin:18px 0 8px}p{line-height:1.6;font-size:14px}.intro{font-size:17px;color:#627069;max-width:700px}.muted{font-size:12px;color:#6b786f}.login form{display:grid;gap:18px;margin-top:30px}label{display:grid;gap:8px;font-size:13px;font-weight:600}input,textarea{width:100%;background:#fff;border:1px solid #c5cfc3;border-radius:7px;padding:13px;color:inherit}input:focus,textarea:focus{outline:2px solid #779b7d;outline-offset:2px}textarea{resize:vertical;margin-bottom:14px}.heading{padding:34px 0}.heading h1{font-size:42px}.meta{display:flex;gap:12px;align-items:center;flex-wrap:wrap;font-size:12px;color:#6b786f}.columns{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(260px,1fr);gap:24px}.card{background:#fffefa;border:1px solid #dce1d5;border-radius:12px;padding:24px;margin-bottom:20px}.ask p{color:#6b786f}.section-title{display:flex;align-items:center;justify-content:space-between;margin:30px 0 18px}.section-title h2{margin:0}.request{border-bottom:1px solid #e5e7df;padding-bottom:15px;color:#6b786f}.notice,.error{background:#f8ecd3;color:#634d27;padding:12px 14px;border-radius:7px;font-size:13px}.error{position:sticky;bottom:16px;box-shadow:0 4px 24px #0001}.empty{padding:24px 0;color:#6b786f}.group-heading{margin:26px 0 4px;font-size:15px}.group-heading+.muted{margin:0 0 14px}.commitment+ .commitment{border-top:1px solid #e5e7df}.allowance{font:30px Georgia,serif}.allowance span{font-size:18px;color:#788579}details{border-bottom:1px solid #e5e7df;padding:13px 0;font-size:13px}summary{cursor:pointer;line-height:1.5}.source{white-space:pre-wrap}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px}footer{padding:42px 0 14px;font-size:12px;color:#879285}.loading{padding:80px 0}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}@media(max-width:700px){main{padding:20px}.columns{grid-template-columns:1fr}.card{padding:20px}.login{margin:45px auto}.heading h1{font-size:36px}.heading{padding:26px 0}.meta time{font-size:11px}}
</style>
